int jump(vector<int>& a) {
    int jumps = 0, end = 0, far = 0;
    for (int i = 0; i + 1 < (int)a.size(); ++i) {
        far = max(far, i + a[i]);
        if (i == end) { ++jumps; end = far; }
    }
    return jumps;
}

public int jump(int[] a) {
    int jumps = 0, end = 0, far = 0;
    for (int i = 0; i + 1 < a.length; i++) {
        far = Math.max(far, i + a[i]);
        if (i == end) { jumps++; end = far; }
    }
    return jumps;
}
